import {CollectionPanel,LiveUpdates,AnalysisMethod,OriginalLinks,collectionQuery} from './collection-ui';
import React,{useState,useEffect,useRef,createContext,useContext} from 'react';
import {createRoot} from 'react-dom/client';
import {BrowserRouter,Routes,Route,Link,NavLink,useParams,useNavigate,useLocation,useSearchParams,Navigate} from 'react-router-dom';
import {QueryClient,QueryClientProvider,useQuery,useQueryClient} from '@tanstack/react-query';
import {Building2,Boxes,Cable,LayoutDashboard,Newspaper,Library,Bookmark,History,Settings as SettingsIcon,Info,MessageCircle,X,ArrowUpRight,ArrowRight,ArrowLeft,Network,Menu,Search,Plus,RefreshCw,Download,Check,AlertTriangle,ChevronRight,FileText,SlidersHorizontal,ExternalLink,ShieldCheck} from 'lucide-react';
import {api,Data,roles,date,money,flag,eventWord,bankEmpty,assistantText,todayMoscow,sourceDate,analysisLabel} from './api';
import {BankView,Consequences,SourceMetadata} from './insight-parts';
import './styles.css';
const qc=new QueryClient({defaultOptions:{queries:{retry:1,refetchOnWindowFocus:false,staleTime:1000}}});
const Ctx=createContext<Data>({});
const useApp=()=>useContext(Ctx);
const statusLabel:Record<string,string>={queued:'В очереди',running:'Выполняется',ready:'Готово',completed:'Готово',completed_with_limits:'Готово с ограничениями',failed:'Ошибка',cancelled:'Отменён',budget_exceeded:'Лимит бюджета',needs_ocr:'Нужен OCR',duplicate:'Дубликат'};
function Button({children,onClick,secondary=false,disabled=false,...rest}:any){return <button className={'btn '+(secondary?'secondary':'primary')} disabled={disabled} onClick={onClick} {...rest}>{children}</button>}
function Tag({children,tone='neutral'}:any){return <span className={'tag '+tone}>{children}</span>}
function Panel({children,className='',...rest}:any){return <section className={'panel '+className} {...rest}>{children}</section>}
function Empty({title,text,children}:any){return <Panel className="empty"><FileText size={64} aria-hidden="true"/><h2>{title}</h2><p className="muted">{text}</p>{children}</Panel>}
function Loading(){return <div className="skeleton" aria-busy="true" role="status">Загрузка…</div>}
function Failure({error,refetch}:any){return <Panel><AlertTriangle aria-hidden="true"/><h2>Не удалось загрузить данные</h2><p role="alert">{error?.message||'Нет соединения с сервером'}</p><Button secondary onClick={()=>refetch()}>Повторить</Button></Panel>}
function Modal({title,children,onClose,drawer=false,closeLabel}:any){
 const ref=useRef<HTMLDialogElement>(null);
 useEffect(()=>{const trigger=document.activeElement as HTMLElement;const d=ref.current!;d.showModal();return()=>{d.close();if(trigger?.isConnected)trigger.focus()}},[]);
 return <dialog ref={ref} className={drawer?'drawer':'modal'} aria-label={title} onCancel={e=>{e.preventDefault();onClose()}} onClick={e=>{if(e.target===ref.current){const r=ref.current!.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)onClose()}}}><div className="dialog-head"><h2>{title}</h2><button className="icon-btn" onClick={onClose} aria-label={closeLabel||'Закрыть '+title}><X aria-hidden="true"/></button></div>{children}</dialog>
}
function App(){
 const me=useQuery({queryKey:['me'],queryFn:()=>api('/me')});const [toast,setToast]=useState('');const [assistant,setAssistant]=useState(false);
 useEffect(()=>{if(toast){const timer=setTimeout(()=>setToast(''),6000);return()=>clearTimeout(timer)}},[toast]);
 if(me.isPending)return <Loading/>;if(me.error)return <Failure error={me.error} refetch={me.refetch}/>;
 return <Ctx.Provider value={{me:me.data,notify:setToast,openAssistant:()=>setAssistant(true)}}><Routes><Route path="/*" element={<Workspace/>}/></Routes>{assistant&&<Modal title="AI-помощник" closeLabel="Закрыть AI-помощника" onClose={()=>setAssistant(false)}><Tag>Скоро</Tag><div className="assistant-icon"><MessageCircle size={48} aria-hidden="true"/></div><p>{assistantText}</p><Button className="btn primary full" onClick={()=>setAssistant(false)}>Понятно</Button></Modal>}{toast&&<div className="toast" role="status">{toast}<button className="icon-btn" aria-label="Закрыть уведомление" onClick={()=>setToast('')}><X size={18}/></button></div>}</Ctx.Provider>
}
function Workspace(){
 const {me,notify,openAssistant}=useApp();const loc=useLocation();const nav=useNavigate();const client=useQueryClient();const [menu,setMenu]=useState(false);const [avatar,setAvatar]=useState(false);
 const uid=(loc.pathname.match(/\/companies\/([^/]+)/)?.[1])||new URLSearchParams(loc.search).get('companyId')||me.preferences.company_id||'U_9250';
 const start=loc.pathname==='/select-company';const dark=loc.pathname==='/business/home'||loc.pathname==='/context'||loc.pathname==='/context/map'||loc.pathname.includes('/overview');
 const companies=useQuery({queryKey:['companies'],queryFn:({signal})=>api('/companies',{signal})});
 const change=async(id:string)=>{try{await api('/me/preferences',{method:'PATCH',body:JSON.stringify({company_id:id})});await client.invalidateQueries({queryKey:['me']});setMenu(false);nav(`/companies/${id}/overview`)}catch(e:any){notify(e.message)}};
 const liveState=useQuery(collectionQuery());
 const role=me.preferences.role;
 const setRole=async(r:string)=>{await api('/me/preferences',{method:'PATCH',body:JSON.stringify({role:r})});await client.invalidateQueries({queryKey:['me']});notify('Роль изменена. Обновите анализ, чтобы учесть новые приоритеты')};
 const links=[['Сводка',`/companies/${uid}/overview`,LayoutDashboard],['Новости',`/companies/${uid}/news`,Newspaper],['Карта влияния',`/context/map?companyId=${uid}`,Network],['Профиль компании',`/companies/${uid}/profile`,Building2],['Источники','/sources',Library],['Сохранённое',`/companies/${uid}/saved`,Bookmark],['История',`/companies/${uid}/history`,History]] as const;
 const navigation=<><div className="nav-title">Альфа Контекст<small>Новости для вашего бизнеса</small></div>{links.map(([label,url,Icon])=><NavLink key={label} to={url} onClick={()=>setMenu(false)}><Icon size={20} aria-hidden="true"/>{label}</NavLink>)}<div className="nav-bottom"><button onClick={()=>{openAssistant()}}><MessageCircle size={20} aria-hidden="true"/>AI-помощник</button><NavLink to="/settings" onClick={()=>setMenu(false)}><SettingsIcon size={20} aria-hidden="true"/>Настройки</NavLink><NavLink to="/about" onClick={()=>setMenu(false)}><Info size={20} aria-hidden="true"/>О проекте</NavLink></div></>;
 return <div className={dark?'app dark':'app light'}><a className="skip" href="#main">Перейти к содержимому</a><header className={start?'start-header':''}><Link className="brand" to="/business/home" aria-label="Альфа-Бизнес, главная"><span className="logo">А</span><span>Альфа-Бизнес</span></Link>{dark&&<nav className="bank-nav"><Link to="/business/home">Главная</Link><Link to="/bank/payments">Платежи</Link><Link className="active" to={`/companies/${uid}/overview`}>Контекст</Link><Link to="/bank/services">Сервисы</Link></nav>}<div className="header-right"><span className="mode" title="Профили обезличены; происхождение материалов и метод анализа указаны отдельно">{(liveState.data?.mode==='live'||liveState.data?.articles>0)?'Свежие внешние источники':'Демонстрационные данные'}</span>{!start&&<><select aria-label="Выберите компанию" value={uid} onChange={e=>change(e.target.value)}>{(companies.data?.items||[]).map((c:Data)=><option key={c.id} value={c.id}>{c.id} · {c.industry}</option>)}</select><select className="role-select" aria-label="Ваша роль" value={role} onChange={e=>setRole(e.target.value)}>{Object.entries(roles).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select><button className="avatar" aria-label="Меню пользователя" onClick={()=>setAvatar(true)}>Д</button><button className="icon-btn menu-toggle" aria-label="Открыть меню" onClick={()=>setMenu(true)}><Menu/></button></>}{start&&<Link className="btn secondary" to="/about">О проекте</Link>}</div></header>{!start&&!dark&&<aside className="sidebar"><nav>{navigation}</nav></aside>}{menu&&<Modal title="Навигация" drawer onClose={()=>setMenu(false)}><nav className="mobile-nav">{navigation}</nav><label>Ваша роль<select value={role} onChange={e=>setRole(e.target.value)}>{Object.entries(roles).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label></Modal>}{avatar&&<Modal title="Демо-пользователь" onClose={()=>setAvatar(false)}><p>Системная роль: {me.system_role}</p><p>Локальная демонстрационная сессия</p><Link className="btn secondary" to="/select-company" onClick={()=>setAvatar(false)}>Выбрать компанию</Link></Modal>}<main id="main" className={start?'start-main':dark?'brief-main':'workspace-main'}><Routes><Route path="/" element={<Navigate replace to={me.preferences.company_id?`/companies/${me.preferences.company_id}/overview`:'/select-company'}/>}/><Route path="/select-company" element={<SelectCompanies companies={companies} setRole={setRole} change={change}/>}/><Route path="/business/home" element={<BankHome uid={uid}/>}/><Route path="/companies/:uid/overview" element={<Overview uid={uid}/>}/><Route path="/context" element={<Overview uid={uid}/>}/><Route path="/context/map" element={<InfluenceMap uid={uid}/>}/><Route path="/companies/:uid/news" element={<News uid={uid}/>}/><Route path="/companies/:uid/insights/:iid" element={<Detail uid={uid}/>}/><Route path="/companies/:uid/insights/:iid/print" element={<Detail uid={uid} print/>}/><Route path="/companies/:uid/profile" element={<Profile uid={uid}/>}/><Route path="/companies/:uid/saved" element={<News uid={uid} saved/>}/><Route path="/companies/:uid/history" element={<RunHistory uid={uid}/>}/><Route path="/runs/:rid" element={<RunTrace/>}/><Route path="/events/:eid/compare" element={<Comparison/>}/><Route path="/sources" element={<Sources/>}/><Route path="/sources/import" element={<ImportPage/>}/><Route path="/settings" element={<SettingsPage/>}/><Route path="/about" element={<About/>}/><Route path="/bank/:kind" element={<Empty title="Раздел банка не подключён" text="Прототип содержит новостную аналитику. Для банковских операций необходима интеграция с Альфа-Бизнесом."><Link className="btn primary" to="/business/home">На главную</Link></Empty>}/><Route path="*" element={<Empty title="Страница не найдена" text="Проверьте адрес или вернитесь к сводке"><Link className="btn primary" to="/select-company">Выбрать компанию</Link></Empty>}/></Routes></main>{dark&&!start&&<footer className="brief-footer"><nav>{links.map(([label,url])=><Link key={label} to={url}>{label}</Link>)}<button onClick={openAssistant}>AI-помощник</button><Link to="/settings">Настройки</Link></nav><p>Прототип для хакатона · Обезличенные данные · Учебные события · 23 октября 2026</p></footer>}<LiveUpdates uid={uid} role={role} notify={notify}/><SourceOverlay/></div>
}
function SelectCompanies({companies,setRole,change}:any){const {me}=useApp();const collection=useQuery(collectionQuery());if(companies.isPending)return <Loading/>;if(companies.error)return <Failure {...companies}/>;const icons=[Building2,Boxes,Cable];return <><h1>Альфа Контекст</h1><p className="lead">Важные события и их возможное влияние на ваш бизнес</p><div className="notice">Выберите компанию и роль. Сервис объяснит связь новостей с вашим бизнесом и покажет основания выводов.<br/><span className="muted">{(collection.data?.mode==='live'||collection.data?.articles>0)?'Профили компаний обезличены. Свежие публикации поступают из внешних источников.':'Вы смотрите демонстрацию. События помечены как учебные.'}</span></div><label className="role-row">Ваша роль<select value={me.preferences.role} onChange={e=>setRole(e.target.value)}>{Object.entries(roles).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><div className="company-grid">{companies.data.items.map((c:Data,n:number)=>{const Icon=icons[n%3];return <Panel className="company-card" key={c.id}><div className="row between"><div className="industry-icon"><Icon size={32}/></div><Tag>По отчёту первого этапа</Tag></div><h2>{c.id}</h2><p>{c.industry}</p><small className="muted">Годовая выручка</small><strong className="revenue">{money(c.revenue_decimal)}</strong><div className="chips">{c.products.credit&&<Tag>Кредит</Tag>}{c.products.leasing&&<Tag>Лизинг</Tag>}</div>{!c.products.credit&&<p className="muted">Кредитный признак не отмечен</p>}<p>ФТС: {c.countries.join(', ')}</p><Button onClick={()=>change(c.id)}>Открыть сводку <ArrowRight size={18}/></Button></Panel>})}</div><p className="muted page-foot">Прототип для хакатона. Используются обезличенные данные.</p></>}
function BankHome({uid}:any){return <><div className="page-head"><div><span className="eyebrow">АЛЬФА-БИЗНЕС · ДЕМО</span><h1>Ваш бизнес — в контексте</h1><p className="muted">События, которые помогают вовремя задать правильный вопрос.</p></div></div><Link to={`/companies/${uid}/overview`} className="bank-entry"><div><Tag>Альфа Контекст</Tag><h2>События, важные<br/>вашему бизнесу</h2><p>От внешнего события — к возможному влиянию и источникам.</p><span className="btn primary">Открыть Контекст <ArrowRight size={20}/></span></div><Network size={140} strokeWidth={1} aria-hidden="true"/></Link><p className="muted">Демонстрационная главная. Банковские операции не подключены.</p></>}
function useRun(uid:string){const {me,notify}=useApp();const client=useQueryClient();const [rid,setRid]=useState('');const [starting,setStarting]=useState(false);const run=useQuery({queryKey:['run-poll',rid],enabled:!!rid,queryFn:()=>api('/runs/'+rid),refetchInterval:q=>['queued','running'].includes(q.state.data?.status)?2000:false});useEffect(()=>{if(run.data&& !['queued','running'].includes(run.data.status)){client.invalidateQueries({queryKey:['overview',uid]});client.invalidateQueries({queryKey:['news',uid]});client.invalidateQueries({queryKey:['comparison']});client.invalidateQueries({queryKey:['history',uid]});notify(run.data.status.startsWith('completed')?'Анализ обновлён':run.data.payload.error?.message||statusLabel[run.data.status]);}},[run.data?.status,rid]);useEffect(()=>{setRid('')},[uid]);const start=async()=>{setStarting(true);try{const s=await api('/settings');const r=await api(s.mode==='live'?'/analysis/batches':`/companies/${uid}/runs`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({role:me.preferences.role,mode:s.mode,as_of:new Date().toISOString()})});setRid(r.run_id||r.run_ids[uid]);client.invalidateQueries({queryKey:['collection']})}catch(e:any){notify(e.message)}finally{setStarting(false)}};return {start,starting,busy:starting||['queued','running'].includes(run.data?.status),data:run.data,rid}}
function Progress({run}:any){const {me}=useApp();return run.busy&&<Panel className="progress"><div><h2>Готовим персональную сводку</h2><p>Шаг {Math.min(7,(run.data?.payload.step||0)+1)} из 7 · {run.data?.payload.steps?.at(-1)?.name||'План анализа'}</p></div><div className="actions">{run.rid&&me.system_role!=='viewer'&&<Link to={'/runs/'+run.rid}>Открыть ход анализа</Link>}<Button secondary onClick={()=>api(`/runs/${run.rid}/cancel`,{method:'POST'})} disabled={!run.rid}>Отменить</Button></div></Panel>}
function Overview({uid}:any){const {me}=useApp();const [sp]=useSearchParams();const run=useRun(uid);const data=useQuery({queryKey:['overview',uid,me.preferences.role,sp.get('runId')],queryFn:({signal})=>api(`/companies/${uid}/overview?role=${me.preferences.role}${sp.get('runId')?'&run_id='+sp.get('runId'):''}`,{signal})});if(data.isPending)return <Loading/>;if(data.error)return <Failure {...data}/>;const o=data.data,c=o.company;const top=o.items[0];return <><div className="page-head"><div><h1>Что важно для вашего бизнеса сегодня</h1><p className="brief-meta"><span className="mode">{o.items.some((item:Data)=>!item.is_synthetic)?'Свежие внешние источники':'Демонстрационные данные'}</span>{c.id} · {c.industry} · {roles[o.run?.role||me.preferences.role]} · {o.run?'Анализ на '+date(o.run.as_of).split(',')[0]:'Анализ ещё не запускался'}</p></div><div className="actions"><Link className="btn dark-secondary" to={`/context/map?companyId=${uid}`}><Network size={20}/>Карта влияния</Link><Button secondary disabled={run.busy} onClick={run.start}><RefreshCw size={18}/>Обновить анализ</Button></div></div>{sp.get('runId')&&<div className="notice">Вы смотрите сохранённую версию от {date(o.run?.created_at)} <Link to={`/companies/${uid}/overview`}>К последней версии</Link></div>}<Progress run={run}/>{!o.run?<Empty title="Сводка ещё не готова" text="Запустите анализ по данным выбранной компании"><Button onClick={run.start} disabled={run.busy}>Подготовить сводку</Button></Empty>:<div className="brief-grid"><section className="hero"><span className="eyebrow">ПЕРСОНАЛЬНЫЙ БРИФ · {o.run?.mode==='live'?'СВЕЖИЕ ИСТОЧНИКИ':'ТЕСТОВЫЙ РЕЖИМ'}</span><h2>{o.kpi.events?`${o.kpi.events} ${eventWord(o.kpi.events)}, которые требуют внимания`:'Всё спокойно. Значимых событий пока нет'}</h2><p>Отобрали главное с учётом вашей компании</p><div className="chips">{c.countries.length>0&&<span>Страны ФТС</span>}{c.products.credit&&<span>Кредит</span>}{c.products.leasing&&<span>Лизинг</span>}</div>{top&&<Link className="btn primary" to={`/companies/${uid}/insights/${top.id}`}>Открыть бриф <ArrowRight size={20}/></Link>}<Radar/></section><div className="counter-stack"><Counter title={o.kpi.opportunities?`${o.kpi.opportunities} возможностей`:'Пока нет возможностей'} text={o.kpi.opportunities?'Условные возможности: проверьте основания и условия применимости':'Недостаточно оснований для выделения возможностей'} tone="aqua" href={o.kpi.opportunities?`/companies/${uid}/news?effect=opportunity`:null}/><Counter title={`${o.kpi.risks} ${o.kpi.risks%100>=11&&o.kpi.risks%100<=14?'рисков':o.kpi.risks%10===1?'риск':o.kpi.risks%10>=2&&o.kpi.risks%10<=4?'риска':'рисков'}`} text="Финансирование и отраслевые зависимости требуют проверки" tone="charcoal" href={o.kpi.risks?`/companies/${uid}/news?effect=risk`:null}/></div><div className="brief-events"><div className="row between"><h2>Приоритетные события</h2><Link className="inverse-link" to={`/companies/${uid}/news`}>Все события <ArrowRight size={18}/></Link></div>{o.items.length?o.items.map((i:Data)=><EventCard key={i.id} i={i} brief/>):<Empty title="За этот период значимых событий не найдено" text="Попробуйте расширить период"/>}</div><div className="brief-right"><ProfileSummary c={c}/><Panel><h2>Аналитика Альфа-Банка</h2><p>{o.items.some((item:Data)=>item.bank_view?.claims?.length)?"В приоритетных событиях есть выдержки из материалов банка":"Для приоритетных событий подтверждённая позиция банка не найдена"}</p><p className="muted">Даты и страницы указаны в разборе. Учебные PDF отдельно помечены.</p><Link to="/sources?tab=bank">Посмотреть источники <ArrowRight size={18}/></Link></Panel><Panel><h2>Выводы требуют проверки</h2><p>Оценки показывают возможные последствия и зависят от полноты данных.</p></Panel></div></div>}</>}
function Radar(){return <svg className="radar" viewBox="0 0 340 300" aria-hidden="true"><defs><radialGradient id="red"><stop stopColor="#ff8279"/><stop offset="1" stopColor="#d92d20"/></radialGradient></defs><circle cx="178" cy="149" r="116" fill="#ffffff20" stroke="#ffffff66"/><circle cx="178" cy="149" r="94" fill="url(#red)"/><circle cx="178" cy="149" r="72" fill="none" stroke="#ffffff55"/><circle cx="178" cy="149" r="48" fill="none" stroke="#ffffff55"/><path d="M178 149 L126 72 A94 94 0 0 1 266 116 Z" fill="#ffffff25"/><path d="M178 55V243M84 149H272" stroke="#ffffff55"/><text x="178" y="168" textAnchor="middle" fill="white" fontSize="52" fontWeight="700">А</text><rect x="18" y="160" width="108" height="68" rx="14" fill="#e5ddff" stroke="#ffffff99" transform="rotate(-7 70 194)"/><path d="M48 182h38M48 194h50M48 206h28" stroke="#69588a" strokeWidth="4"/><rect x="205" y="44" width="115" height="65" rx="14" fill="#dfd5ff" stroke="#ffffff99" transform="rotate(7 260 76)"/><path d="M228 87l17-18 16 8 29-20" fill="none" stroke="#69588a" strokeWidth="5"/></svg>}
function Counter({title,text,tone,href}:any){const body=<><ArrowUpRight size={32} aria-hidden="true"/><h2>{title}</h2><p>{text}</p></>;return href?<Link className={'counter '+tone} to={href}>{body}</Link>:<section className={'counter '+tone}>{body}</section>}
function ProfileSummary({c}:any){return <Panel className="profile-summary"><h2>Ваш контекст</h2><div className="row"><Building2 size={32}/><div><strong>{c.id}</strong><p>{c.industry}</p></div></div><p>Выручка {money(c.revenue_decimal)}</p><p>ФТС: {c.countries.join(', ')}</p><p>{c.products.credit?'Кредит и лизинг':'Лизинг · кредитный признак не отмечен'}</p><p className="muted">Товары и условия обязательств неизвестны.</p><Link to={`/companies/${c.id}/profile`}>Посмотреть профиль <ArrowRight size={18}/></Link></Panel>}
function SaveButton({i}:any){const {notify}=useApp();const client=useQueryClient();const [busy,setBusy]=useState(false);return <button className={'icon-btn '+(i.saved?'saved':'')} aria-label={i.saved?'Удалить из сохранённого':'Сохранить инсайт'} aria-pressed={!!i.saved} disabled={busy} onClick={async()=>{setBusy(true);try{await api(`/companies/${i.company_id}/saved/${i.id}`,{method:i.saved?'DELETE':'PUT'});await client.invalidateQueries();notify(i.saved?'Удалено из сохранённого':'Сохранено')}catch(e:any){notify('Не удалось сохранить. Попробуйте ещё раз')}finally{setBusy(false)}}}><Bookmark fill={i.saved?'currentColor':'none'} size={20}/></button>}
function EventCard({i,brief=false}:any){const [why,setWhy]=useState(false);const [sp,setSp]=useSearchParams();return <Panel className={'event-card '+(brief?'brief-event':'')}><div className="row between"><div className="chips"><Tag tone={i.impact==='risk'?'risk':i.impact==='opportunity'?'opportunity':'neutral'}>{({risk:'Риск',opportunity:'Возможность',mixed:'Смешанное влияние',neutral:'Нейтрально'} as Record<string,string>)[i.impact]||'Требует уточнения'}</Tag>{i.relevance.score<50&&<Tag>Требует уточнения</Tag>}<Tag>{i.is_synthetic?'Учебное событие':'Внешний источник'}</Tag></div><span className="muted score">Релевантность: {i.relevance.score}/100</span></div><h2><Link to={`/companies/${i.company_id}/insights/${i.id}`}>{i.title}</Link></h2>{brief?<div className="explanation-grid"><div className="fact-tile"><strong>{i.is_synthetic?'Факт · демо':'Факт из внешнего источника'}</strong><p>{i.facts[0].text}</p></div><div className="bank-tile"><strong>Аналитика банка</strong><p>{i.bank_view?.claims?.[0]?.text||bankEmpty}</p></div><div className="ai-tile"><strong>{analysisLabel(i)}</strong><p>{i.company_links[0].text}</p></div></div>:<p>{i.summary}</p>}<button className="why" aria-expanded={why} onClick={()=>setWhy(!why)}><ShieldCheck size={20}/><span>Почему важно: {i.company_links[0].text}</span></button>{why&&<div className="notice"><ul>{i.relevance.reasons.map((s:string)=><li key={s}>{s}</li>)}</ul><Link to={`/companies/${i.company_id}/profile`}>Данные компании</Link></div>}<AnalysisMethod insight={i}/><OriginalLinks insight={i}/><p className="muted">{i.source_metadata?.[0]?.publisher||(i.is_synthetic?'Учебный источник':'Внешний источник')} · {date(i.published_at)} · Часть данных отсутствует</p><div className="event-footer"><Link className="btn secondary" to={`/companies/${i.company_id}/insights/${i.id}`}>Подробнее</Link><Link className="btn secondary" to={`/events/${i.event_id}/compare`}>Сравнить</Link><button className="text-btn" onClick={()=>{const next=new URLSearchParams(sp);next.set('drawer',i.source_document_ids[0]);setSp(next)}}>Источники · {i.source_document_ids.length}</button><SaveButton i={i}/></div></Panel>}
function News({uid,saved=false}:any){const {me}=useApp();const [sp,setSp]=useSearchParams();const [draft,setDraft]=useState(sp.get('q')||'');const run=useRun(uid);useEffect(()=>setDraft(sp.get('q')||''),[sp.get('q')]);useEffect(()=>{const t=setTimeout(()=>{if(draft!==(sp.get('q')||''))change('q',draft)},300);return()=>clearTimeout(t)},[draft]);function change(k:string,v:string){const p=new URLSearchParams(sp);v?p.set(k,v):p.delete(k);p.delete('page');setSp(p)}const qs=new URLSearchParams(sp);qs.set('role',me.preferences.role);qs.delete('drawer');const data=useQuery({queryKey:['news',uid,saved,qs.toString()],queryFn:({signal})=>api(`/companies/${uid}/${saved?'saved':'insights'}?${qs}`,{signal})});const [custom,setCustom]=useState(false);const [start,setStart]=useState(sp.get('start')||'');const [end,setEnd]=useState(sp.get('end')||'');const [dateError,setDateError]=useState('');return <><div className="page-head"><div><h1>{saved?'Сохранённые инсайты':'Значимые события'}</h1><p className="muted">{saved?'Для '+uid:'Новости, отобранные с учётом профиля '+uid}</p></div>{!saved&&<Button onClick={run.start} disabled={run.busy}>Обновить анализ</Button>}</div><Progress run={run}/><Panel className="filters"><div className="filter-row"><label className="search-label"><Search size={20}/><input aria-label="Поиск событий" placeholder="Найти событие или источник" value={draft} onChange={e=>setDraft(e.target.value)} onKeyDown={e=>{if(e.key==='Escape')setDraft('')}}/></label>{!saved&&<><select aria-label="Период" value={sp.get('period')||'all'} onChange={e=>{if(e.target.value==='custom'){setCustom(true);return}const next=new URLSearchParams(sp);next.set('period',e.target.value);next.delete('page');if(e.target.value!=='all'){const d=new Date(todayMoscow()+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-Number(e.target.value)+1);next.set('start',d.toISOString().slice(0,10));next.set('end',todayMoscow())}else{next.delete('start');next.delete('end')}setSp(next)}}><option value="all">Все даты</option><option value="7">Последние 7 дней</option><option value="30">Последние 30 дней</option><option value="90">Последние 90 дней</option><option value="custom">Выбрать даты</option></select><select aria-label="Влияние" value={sp.get('effect')||''} onChange={e=>change('effect',e.target.value)}><option value="">Любое влияние</option><option value="risk">Риск</option><option value="opportunity">Возможность</option><option value="mixed">Смешанное влияние</option><option value="neutral">Нейтральное</option></select></>}<Button secondary onClick={()=>{setDraft('');setSp({})}}>Сбросить</Button></div>{!saved&&<div className="chips topic-filters">{[['','Все'],['no-bank','Отрасль'],['rate','Ставка и финансы'],['copper','Сырьё'],['conflict','Регулирование'],['china','Внешняя торговля'],['fx','Валюты'],['logistics','Логистика'],['demand','Спрос'],['labor','Рынок труда'],['energy','Энергия']].map(([k,v])=><button className={((sp.get('topics')||'').split(',').includes(k)?'selected':'')} aria-pressed={(sp.get('topics')||'').split(',').includes(k)} key={k} onClick={()=>{const active=(sp.get('topics')||'').split(',').filter(Boolean);change('topics',!k?'':active.includes(k)?active.filter(s=>s!==k).join(','):[...active,k].join(','))}}>{v}</button>)}</div>}</Panel><div className="row between list-meta"><p>Найдено: {data.data?.total??'—'}</p><select aria-label="Сортировка" value={sp.get('sort')||'relevance'} onChange={e=>change('sort',e.target.value)}><option value="relevance">По значимости</option><option value="newest">Сначала новые</option><option value="oldest">Сначала старые</option></select></div>{data.isPending?<Loading/>:data.error?<Failure {...data}/>:data.data.total?<><div className="event-list">{data.data.items.map((i:Data)=><EventCard key={i.id} i={i}/>)}</div><div className="pagination"><Button secondary disabled={Number(sp.get('page')||1)<=1} onClick={()=>{const p=new URLSearchParams(sp);p.set('page',String(Number(sp.get('page')||1)-1));setSp(p)}}>Назад</Button><span>Страница {sp.get('page')||1} из {Math.max(1,Math.ceil(data.data.total/10))}</span><Button secondary disabled={Number(sp.get('page')||1)*10>=data.data.total} onClick={()=>{const p=new URLSearchParams(sp);p.set('page',String(Number(sp.get('page')||1)+1));setSp(p)}}>Далее</Button></div></>:<Empty title={saved?'Здесь будут сохранённые инсайты':'Ничего не найдено'} text={saved?'Нажмите на значок закладки у интересующего события':'Измените запрос или сбросьте фильтры'}><Link className="btn secondary" to={`/companies/${uid}/news`}>{saved?'Перейти к событиям':'Сбросить фильтры'}</Link></Empty>}{custom&&<Modal title="Выберите период" onClose={()=>setCustom(false)}><label>С даты<input type="date" value={start} onChange={e=>setStart(e.target.value)}/></label><label>По дату<input type="date" value={end} onChange={e=>setEnd(e.target.value)}/></label>{dateError&&<p role="alert">{dateError}</p>}<div className="actions"><Button onClick={()=>{if(start>end){setDateError('Дата начала не может быть позже даты окончания');return}const p=new URLSearchParams(sp);p.set('start',start);p.set('end',end);p.set('period','custom');p.delete('page');setSp(p);setCustom(false)}}>Применить</Button><Button secondary onClick={()=>setCustom(false)}>Отмена</Button></div></Modal>}</>}
function Detail({uid,print=false}:any){const {iid}=useParams();const {me,notify}=useApp();const [sp,setSp]=useSearchParams();const [negative,setNegative]=useState(false);const [reason,setReason]=useState('Недостаточно оснований');const [comment,setComment]=useState('');const [scenario,setScenario]=useState(false);const d=useQuery({queryKey:['detail',uid,iid],queryFn:({signal})=>api(`/companies/${uid}/insights/${iid}`,{signal})});if(d.isPending)return <Loading/>;if(d.error)return <Failure {...d}/>;const i=d.data;const vote=async(useful:boolean)=>{try{await api(`/insights/${iid}/feedback`,{method:'PUT',body:JSON.stringify({useful,reason:useful?'':reason,comment:useful?'':comment})});setNegative(false);notify('Спасибо за обратную связь')}catch(e:any){notify(e.message)}};return <><Link to={`/companies/${uid}/news`} className="back"><ArrowLeft size={18}/>Назад к событиям</Link><div className="page-head"><h1>{i.title}</h1><div className="actions"><SaveButton i={i}/><a className="btn secondary" href={`/api/v1/insights/${iid}/export`} download><Download size={18}/>Markdown (.md)</a><Link className="btn secondary" to={`/companies/${uid}/insights/${iid}/print`}>Версия для печати</Link>{print&&<Button onClick={()=>window.print()}>Печать</Button>}<Link className="btn secondary" to={`/events/${i.event_id}/compare`}>Сравнить</Link></div></div><div className="chips"><Tag tone={i.impact==='risk'?'risk':i.impact==='opportunity'?'opportunity':'neutral'}>{({risk:'Риск',opportunity:'Возможность',mixed:'Смешанное влияние',neutral:'Нейтрально'} as Record<string,string>)[i.impact]||'Требует уточнения'}</Tag><Tag>Релевантность: {i.relevance.score}/100</Tag><Tag>Анализ на {date(i.as_of).split(',')[0]}</Tag><Tag>{i.is_synthetic?'Учебное событие':'Внешний источник'}</Tag></div><AnalysisMethod insight={i}/><OriginalLinks insight={i}/><div className="detail-grid"><div className="stack"><Panel className="fact-tile"><Tag>Факты из источников</Tag><h2>Что произошло</h2>{i.facts.map((f:Data)=><p key={f.claim_id}>{f.text} <button className="text-btn" onClick={()=>{const p=new URLSearchParams(sp);p.set('drawer',f.evidence_ids[0].split('#')[0]);setSp(p)}}>[{Math.max(1,i.source_document_ids.indexOf(f.evidence_ids[0].split('#')[0])+1)}]</button></p>)}</Panel><Panel className="bank-tile"><Tag>Аналитика банка</Tag><h2>Позиция Альфа-Банка</h2><BankView insight={i} openSource={id=>{const p=new URLSearchParams(sp);p.set('drawer',id);setSp(p)}}/></Panel><Panel className="ai-tile"><Tag>Условный вывод</Tag><h2>Почему это важно для {uid}</h2>{i.company_links.map((l:Data,n:number)=><p key={n}>{l.text}</p>)}<Link to={`/companies/${uid}/profile?snapshotRun=${i.run_id}#provenance`}>Данные компании</Link><h2>Возможные последствия</h2><Consequences items={i.hypotheses}/></Panel><Panel><Tag>Варианты действий</Tag><h2>Что проверить и сделать</h2>{i.actions.map((a:Data,n:number)=><div key={n}><p>{a.text}</p><small className="muted">Нужны данные: {a.requires_data.join(', ')}</small></div>)}<Button secondary onClick={()=>setScenario(true)}>Сравнить сценарии</Button></Panel><Panel className="warning-tile"><h2>Ограничения анализа</h2><p>Вывод условный: требуется уточнение</p><ul>{i.missing_data.map((s:string)=><li key={s}>{s}</li>)}</ul><Link to={`/companies/${uid}/profile#clarify`}>Уточнить профиль</Link></Panel><Panel><h2>Был ли инсайт полезен?</h2><div className="actions"><Button secondary onClick={()=>vote(true)}>Да</Button><Button secondary onClick={()=>setNegative(true)}>Нет</Button></div></Panel></div><aside className="stack"><Panel><h2>Основания вывода</h2><p>Источников: {i.source_document_ids.length}</p><p>Материалов банка: {i.bank_view.document_ids.length}</p><p>Признаков компании: {i.company_links.length}</p><Tag>Часть данных отсутствует</Tag><hr/>{i.source_document_ids.map((id:string,n:number)=><button className="source-button" key={id} onClick={()=>{const p=new URLSearchParams(sp);p.set('drawer',id);setSp(p)}}><FileText size={24}/><span>[{n+1}] {i.source_metadata?.find((source:Data)=>source.id===id)?.publisher||(i.is_synthetic?'Учебный источник':'Внешний источник')}<br/><small>{date(i.published_at)} · Открыть источник</small></span><ChevronRight size={20}/></button>)}{me.system_role!=='viewer'&&<Link to={'/runs/'+i.run_id}>Как получен вывод <ArrowRight size={18}/></Link>}</Panel><Panel><h2>Как читать этот разбор</h2><p>Факт описывает источник. Вывод AI показывает условный механизм связи с компанией. Полнота оснований не равна вероятности прогноза.</p></Panel></aside></div>{negative&&<Modal title="Что можно улучшить?" onClose={()=>setNegative(false)}><label>Причина<select value={reason} onChange={e=>setReason(e.target.value)}>{['Не относится к компании','Недостаточно оснований','Непонятный текст','Другое'].map(s=><option key={s}>{s}</option>)}</select></label><label>Комментарий (необязательно)<textarea placeholder="Комментарий (необязательно)" value={comment} maxLength={1000} onChange={e=>setComment(e.target.value)}/></label><div className="actions"><Button onClick={()=>vote(false)}>Отправить</Button><Button secondary onClick={()=>setNegative(false)}>Отмена</Button></div></Modal>}{scenario&&<Modal title="Возможные сценарии" drawer onClose={()=>setScenario(false)}><p>{uid} · {i.title}</p><div className="scenario-grid">{['Текущие условия','Альтернативные условия'].map(s=><Panel key={s}><h3>{s}</h3><p>Стоимость: может измениться</p><p>Сроки: не уточнены</p><p>Нужны условия договора и коммерческое предложение.</p></Panel>)}</div><p>Числовой эффект недоступен без входных данных и расчётной модели.</p><Link to={`/companies/${uid}/profile#clarify`} onClick={()=>setScenario(false)}>Что уточнить в профиле</Link></Modal>}</>}
function Profile({uid}:any){const {me,notify}=useApp();const [sp]=useSearchParams();const historical=sp.get('snapshotRun');const q=useQuery({queryKey:['profile',uid,historical],queryFn:()=>api(`/companies/${uid}/profile${historical?'?run_id='+historical:''}`)});const [field,setField]=useState('');const [comment,setComment]=useState('');const [terms,setTerms]=useState('unknown');const [route,setRoute]=useState('');const client=useQueryClient();const run=useRun(uid);if(q.isPending)return <Loading/>;if(q.error)return <Failure {...q}/>;const c=q.data;const values=[['ID',c.id,'industry'],['Отрасль',c.industry,'industry'],['ОКВЭД',`${c.okved||'Нет данных'} · ${c.okved_name||''}`,'okved'],['Регион регистрации',c.region,'region'],['Город',c.city,'city'],['Годовая выручка',`${money(c.revenue_decimal)} (${c.revenue_decimal} ₽)`,'revenue_decimal'],['Группа',c.group_id,'group_id']];return <><div className="page-head"><h1>Профиль компании</h1><Link className="btn secondary" to={`/companies/${uid}/overview`}>К сводке</Link></div><div className="notice">{historical&&<>Снимок профиля на момент анализа. <Link to={`/companies/${uid}/profile`}>К текущему профилю</Link><br/></>}Профиль составлен из обезличенных данных. Отсутствующие значения не считаются отрицательными признаками.</div><div className="detail-grid"><div className="stack"><Panel><h2>Основная информация</h2><dl className="profile-values">{values.map(([k,v,f])=><React.Fragment key={k}><dt>{k}</dt><dd>{v||'Нет данных'} <button className="icon-btn small" aria-label={'Происхождение: '+k} onClick={()=>setField(f)}><Info size={16}/></button></dd></React.Fragment>)}</dl></Panel><Panel><h2>Финансовые признаки</h2><dl className="profile-values">{Object.entries({credit:'Кредит',leasing:'Лизинг',rko:'РКО',guarantee:'Гарантия',deposit:'Депозит',salary:'Зарплатный проект',factoring:'Факторинг'}).map(([k,v])=><React.Fragment key={k}><dt>{v}</dt><dd>{flag(c.products[k])}<button className="icon-btn small" aria-label={'Происхождение: '+v} onClick={()=>setField(k)}><Info size={16}/></button></dd></React.Fragment>)}</dl><p className="muted">Неотмеченный кредитный признак не доказывает отсутствие долга.</p></Panel><Panel><h2>Внешнеторговый контекст</h2><div className="chips">{c.countries.map((s:string)=><Tag key={s}>{s}</Tag>)}</div><p>Страна в ФТС не подтверждает зависимость от конкретного товара.</p></Panel><Panel><h2>Платёжные связи</h2><div className="kpi-mini"><div><strong>{c.payment_links?.payers??'—'}</strong><span>Уникальных плательщиков</span></div><div><strong>{c.payment_links?.beneficiaries??'—'}</strong><span>Уникальных получателей</span></div></div><p className="muted">Без самопереводов. Направление платежа не определяет поставщика или покупателя.</p></Panel>{me.system_role!=='viewer'&&!historical&&<Panel id="clarify"><h2>Уточнить профиль</h2><p>Уточнения хранятся отдельно от исходных CSV и не меняют реквизиты компании в банке.</p>{c.clarification&&<p>Сохранено: {c.clarification.comment||'Без комментария'} · версия {c.clarification_version}</p>}<label>Маршрут (если подтверждён)<input value={route} onChange={e=>setRoute(e.target.value)} placeholder="Страна / вид транспорта / регион"/></label><label>Особенности договоров<select value={terms} onChange={e=>setTerms(e.target.value)}><option value="unknown">Неизвестно</option><option value="fixed">Тариф фиксирован</option><option value="floating">Тариф плавающий</option></select></label><label>Комментарий<textarea maxLength={1000} value={comment} onChange={e=>setComment(e.target.value)}/></label><Button disabled={!comment.trim()&&!route.trim()&&terms==='unknown'} onClick={async()=>{try{await api(`/companies/${uid}/profile`,{method:'PATCH',body:JSON.stringify({version:c.clarification_version||0,comment,contract_terms:terms,routes:route?[route]:[]})});await client.invalidateQueries({queryKey:['profile',uid]});notify('Контекст обновлён');run.start()}catch(e:any){notify(e.message)}}}>Сохранить и обновить анализ</Button><Progress run={run}/></Panel>}</div><div className="stack"><Panel><h2>Полнота данных</h2><h3>Известно</h3><p>Отрасль, выручка, регион, продукты, страны ФТС и агрегаты связей.</p><h3>Требует уточнения</h3><ul>{c.unknowns.map((s:string)=><li key={s}>{s}</li>)}</ul></Panel><Panel id="provenance"><h2>Происхождение</h2><Tag>Проверено по CSV</Tag><p>{c.source}</p><p>Строка: {c.id}</p><p>Импорт: {date(c.imported_at)}</p><p>Предыдущий источник: отчёт первого этапа.</p>{me.system_role!=='viewer'&&<Link to="/sources/import?tab=datasets">Импортировать данные</Link>}</Panel></div></div>{field&&<Modal title="Происхождение признака" onClose={()=>setField('')}><dl className="compact-dl">{Object.entries(c.field_evidence[field]||{}).map(([k,v])=><React.Fragment key={k}><dt>{({field:'Поле',raw_value:'Исходное значение',file:'Файл',row_key:'Строка',imported_at:'Импорт',id:'Идентификатор основания'} as Data)[k]||k}</dt><dd>{String(v)}</dd></React.Fragment>)}</dl></Modal>}</>}
function SourceOverlay(){const [sp,setSp]=useSearchParams();const id=sp.get('drawer');const {me,notify}=useApp();const client=useQueryClient();const source=useQuery({queryKey:['source',id],enabled:!!id,queryFn:()=>api('/sources/'+id)});const close=()=>{const p=new URLSearchParams(sp);p.delete('drawer');setSp(p,{replace:true})};if(!id)return null;return <Modal title="Источники и основания" drawer onClose={close}>{source.isPending?<Loading/>:source.error?<Failure {...source}/>:<><h3>{source.data.title}</h3><div className="chips"><Tag>{source.data.is_synthetic?'Учебный документ':source.data.bank_verified?'Материал из подтверждённого корпуса':'Внешний материал'}</Tag>{source.data.kind==='bank'&&source.data.is_synthetic&&<Tag>Учебный документ банка</Tag>}<Tag>{statusLabel[source.data.text_status]||source.data.text_status}</Tag></div><p className="muted">{source.data.publisher} · {sourceDate(source.data)}</p><p>Загружено: {date(source.data.fetched_at)}</p><SourceMetadata source={source.data}/>{source.data.chunks.map((c:Data)=><Panel key={c.id} className="excerpt"><small>{c.page_number?'Страница '+c.page_number:'Текстовый источник'} · Фрагмент {c.id.split('#')[1]}</small><p>{c.text}</p></Panel>)}{source.data.text_status==='needs_ocr'&&<p role="alert">Не удалось извлечь текст. Документу требуется OCR.</p>}<p className="muted">Контрольная сумма: {source.data.sha256}</p>{source.data.file_id&&<a className="btn secondary" href={'/api/v1/sources/'+id+'/file'}>Скачать исходный PDF</a>}{source.data.origin_url&&<a className="btn secondary" href={source.data.origin_url} target="_blank" rel="noopener noreferrer">Открыть оригинал <ExternalLink size={18}/></a>}{me.system_role!=='viewer'&&<div className="actions"><Button secondary onClick={async()=>{try{await api('/sources/'+id,{method:'PATCH',body:JSON.stringify({active:!source.data.active})});client.invalidateQueries({queryKey:['source',id]});notify(source.data.active?'Источник исключён из новых анализов':'Источник включён')}catch(e:any){notify(e.message)}}}>{source.data.active?'Исключить из анализа':'Включить в анализ'}</Button>{['failed','needs_ocr'].includes(source.data.text_status)&&<Button secondary onClick={async()=>{try{await api(`/sources/${id}/reprocess`,{method:'POST'});notify('Повторная обработка запущена')}catch(e:any){notify(e.message)}}}>Повторить обработку</Button>}</div>}</>}</Modal>}
function Sources(){const {me,notify}=useApp();const [sp,setSp]=useSearchParams();const tab=sp.get('tab')||'news';const [search,setSearch]=useState('');const [status,setStatus]=useState('');const [job,setJob]=useState(sp.get('job')||'');const data=useQuery({queryKey:['sources',tab,search,status],queryFn:()=>api(`/sources?tab=${tab}&q=${encodeURIComponent(search)}&status=${status}`)});const client=useQueryClient();const jq=useQuery({queryKey:['job',job],enabled:!!job,queryFn:()=>api('/imports/'+job),refetchInterval:q=>['queued','running'].includes(q.state.data?.status)?1000:false});useEffect(()=>{if(jq.data?.status==='ready')client.invalidateQueries({queryKey:['sources']})},[jq.data?.status]);return <><div className="page-head"><h1>Источники и аналитика</h1>{me.system_role!=='viewer'&&<Link className="btn primary" to="/sources/import"><Plus size={18}/>Добавить материалы</Link>}</div><CollectionPanel admin={me.system_role==='admin'} notify={notify} role={me.preferences.role}/><div className="tabs">{[['news','Новости'],['bank','Аналитика банка'],['datasets','Данные компаний']].map(([k,v])=><button key={k} className={tab===k?'active':''} onClick={()=>setSp({tab:k})}>{v}</button>)}</div>{job&&<Panel className="job-panel"><div className="row between"><h2>Задание импорта</h2><button className="icon-btn" aria-label="Закрыть задание" onClick={()=>setJob('')}><X/></button></div><p role="status">{statusLabel[jq.data?.status]||'Загрузка…'}</p>{jq.data?.payload.error&&<p role="alert">{jq.data.payload.error.message}</p>}{jq.data?.payload.items?.map((item:Data,n:number)=><div key={item.id||item.url||n}>{item.id?<button className="text-btn" onClick={()=>{const p=new URLSearchParams(sp);p.set('drawer',item.id);setSp(p)}}>Открыть импортированный документ</button>:<p>{item.status==='failed'?'Ошибка: ':'Пропущено: '}{item.error?.message||item.reason}</p>}</div>)}{jq.data?.payload.id&&<button className="text-btn" onClick={()=>{const p=new URLSearchParams(sp);p.set('drawer',jq.data.payload.id);setSp(p)}}>Открыть материал</button>}<a href={'/api/v1/imports/'+job+'/report'} className="btn secondary">Скачать отчёт</a></Panel>}<div className="filter-row"><label><span className="sr-only">Найти материал</span><input value={search} placeholder="Найти материал" onChange={e=>setSearch(e.target.value)}/></label><select aria-label="Статус материала" value={status} onChange={e=>setStatus(e.target.value)}><option value="">Все статусы</option><option value="ready">Готово</option><option value="needs_ocr">Нужен OCR</option><option value="failed">Ошибка</option></select></div>{data.isPending?<Loading/>:data.error?<Failure {...data}/>:data.data.items.length?<div className="table-scroll" role="region" aria-label="Таблица источников" tabIndex={0}><table><thead><tr><th>Название</th><th>Тип</th><th>Дата</th><th>Статус</th><th>Действия</th></tr></thead><tbody>{data.data.items.map((s:Data)=><tr key={s.id||s.sha256}><td>{s.title||s.file}{s.is_synthetic&&<div><Tag>Учебный документ</Tag></div>}</td><td>{s.kind==='bank'?(s.is_synthetic?'PDF банка · учебный':s.bank_verified?'Материал банка':'Аналитика · происхождение не подтверждено'):s.kind==='news'?'Новость':s.kind}</td><td>{s.published_at?sourceDate(s):s.accepted!=null?s.accepted+' строк':'Дата не указана'}</td><td>{s.text_status?statusLabel[s.text_status]:'Готово'}{s.active===false&&' · Исключён'}</td><td>{s.id?<button className="text-btn" onClick={()=>{const p=new URLSearchParams(sp);p.set('drawer',s.id);setSp(p)}}>Открыть</button>:<span>{s.encoding} · {s.delimiter}</span>}</td></tr>)}</tbody></table></div>:<Empty title="Источники ещё не добавлены" text="Загрузите материалы для анализа">{me.system_role!=='viewer'?<Link className="btn primary" to="/sources/import">Добавить материалы</Link>:<p>Источники добавляет аналитик</p>}</Empty>}</>}
function UnsavedGuard({dirty}: {dirty:boolean}){const [pending,setPending]=useState('');const nav=useNavigate();useEffect(()=>{if(!dirty)return;const intercept=(e:MouseEvent)=>{const a=(e.target as Element).closest('a[href]') as HTMLAnchorElement|null;if(!a||a.origin!==location.origin||a.pathname===location.pathname&&a.search===location.search||e.metaKey||e.ctrlKey||a.download)return;e.preventDefault();e.stopPropagation();setPending(a.pathname+a.search)};document.addEventListener('click',intercept,true);return()=>document.removeEventListener('click',intercept,true)},[dirty]);return pending?<Modal title="Материал не сохранён" onClose={()=>setPending('')}><p>При переходе введённые данные будут потеряны.</p><div className="actions"><Button onClick={()=>setPending('')}>Остаться</Button><Button secondary onClick={()=>nav(pending)}>Уйти без сохранения</Button></div></Modal>:null}
function ImportPage(){const {me,notify}=useApp();const [sp,setSp]=useSearchParams();const nav=useNavigate();const tab=sp.get('tab')||'url';const [title,setTitle]=useState('');const [text,setText]=useState('');const [url,setUrl]=useState('');const [published,setPublished]=useState('2026-10-22');const [kind,setKind]=useState('news');const [files,setFiles]=useState<File[]>([]);const [preview,setPreview]=useState<Data|null>(null);const [error,setError]=useState('');const [busy,setBusy]=useState(false);
 useEffect(()=>{const handler=(e:BeforeUnloadEvent)=>{if(title||text){e.preventDefault();e.returnValue=''}};window.addEventListener('beforeunload',handler);return()=>window.removeEventListener('beforeunload',handler)},[title,text]);
 if(me.system_role==='viewer')return <Empty title="Нет доступа" text="Источники добавляет аналитик"><Link to="/sources">Посмотреть источники</Link></Empty>;
 const submit=async(check=false)=>{setError('');setBusy(true);try{let r:Data;if(tab==='text')r=await api('/imports/text',{method:'POST',body:JSON.stringify({title,text,published_at:published?published+'T12:00:00+03:00':null,kind,mode:'fixture'})});else if(['url','feed'].includes(tab))r=await api(tab==='feed'?'/imports/feed':'/imports/url',{method:'POST',body:JSON.stringify(tab==='feed'?{url,mode:'fixture',max_items:5}:{url,kind,mode:'fixture',published_at:published?published+'T12:00:00+03:00':null})});else{const body=new FormData();files.forEach(f=>body.append('files',f));body.append('kind',kind);body.append('published_at',published?published+'T12:00:00+03:00':'');body.append('preview',String(check));r=await api(tab==='datasets'?'/imports/datasets':'/imports/files',{method:'POST',body})}if(check){setPreview(r);notify('Структура проверена');return}nav('/sources?tab='+(tab==='datasets'?'datasets':kind==='bank'?'bank':'news')+'&job='+r.job_id);setTitle('');setText('')}catch(e:any){setError(e.message)}finally{setBusy(false)}};
 return <><Link className="back" to="/sources"><ArrowLeft size={18}/>Назад к источникам</Link><h1>Добавить материалы</h1><UnsavedGuard dirty={!!(title||text)&&!busy}/><Panel className="import-form"><div className="tabs">{[['url','По ссылке'],['feed','RSS / Atom'],['file','Файл'],['text','Текст'],['datasets','Данные компаний']].map(([k,v])=><button key={k} className={tab===k?'active':''} onClick={()=>{setSp({tab:k});setError('');setFiles([]);setPreview(null)}}>{v}</button>)}</div><div className="notice">Интерпретация работает в тестовом режиме. Материалы по ссылке сохраняют внешнее происхождение; текст и загруженные файлы считаются учебными до отдельной проверки. Тип материала не подтверждает авторство банка.</div>{['url','feed'].includes(tab)&&<><label>{tab==='feed'?'URL RSS/Atom':'URL материала'}<input type="url" value={url} placeholder="https://…" onChange={e=>setUrl(e.target.value)}/></label><p className="muted">{tab==='feed'?'RSS и Atom: до 5 статей за сбор. Повторный импорт устраняет дубликаты. Отдельные ошибки видны в отчёте.':'Поддерживаются публичные HTML-страницы и PDF. Закрытые разделы и платные подписки не обходятся.'}</p></>}{tab==='text'&&<><label>Заголовок<input value={title} onChange={e=>setTitle(e.target.value)} maxLength={300}/></label><label>Текст материала<textarea value={text} onChange={e=>setText(e.target.value)} maxLength={100000} rows={10}/></label><p className="muted">Введено вручную · От 200 до 100 000 символов</p></>}{['file','datasets'].includes(tab)&&<><label className="dropzone"><FileText size={32}/><strong>{tab==='file'?'Перетащите PDF или выберите файл':'Загрузите таблицы компаний, связей и платежей'}</strong><input type="file" multiple accept={tab==='file'?'.pdf':'.csv,.zip'} onChange={e=>{const list=Array.from(e.target.files||[]);setFiles(list);setPreview(null);if(list.some(f=>f.size>(tab==='file'?20:50)*1024*1024||!(tab==='file'?/\.pdf$/i:/\.(csv|zip)$/i).test(f.name)))setError(tab==='file'?'Формат файла не поддерживается. Загрузите PDF до 20 МБ':'Загрузите CSV или ZIP до 50 МБ');else setError('')}}/><small>{tab==='file'?'PDF до 20 МБ; до 10 файлов за импорт':'CSV / ZIP до 50 МБ; безопасная проверка архива'}</small></label>{files.map(f=><div className="row between file-row" key={f.name}><span>{f.name} · {(f.size/1024).toFixed(1)} КБ</span><button className="icon-btn" aria-label={'Удалить '+f.name} onClick={()=>setFiles(files.filter(x=>x!==f))}><X/></button></div>)}</>}{!['datasets','feed'].includes(tab)&&<><label>Тип материала<select value={kind} onChange={e=>setKind(e.target.value)}><option value="news">Новость / внешний материал</option><option value="bank">Аналитика банка · требует проверки</option></select></label><label>Дата публикации (если не определится автоматически)<input type="date" value={published} onChange={e=>setPublished(e.target.value)}/></label></>}{error&&<p role="alert" className="error-message">{error}</p>}{preview&&<Panel><h2>Предварительная проверка</h2>{preview.files.map((f:Data)=><p key={f.file}>{f.file} · {f.kind} · {f.columns.join(', ')}</p>)}<p>Принято для проверки: {preview.accepted}, отклонено: {preview.rejected}</p><details><summary>Первые строки и сопоставление полей</summary><pre>{JSON.stringify(preview.preview,null,2)}</pre></details></Panel>}<div className="actions">{tab==='datasets'&&<Button secondary disabled={!files.length||busy} onClick={()=>submit(true)}>Проверить структуру</Button>}<Button disabled={busy||files.some(f=>f.size>(tab==='file'?20:50)*1024*1024)||(tab==='file'&&files.some(f=>!/\.pdf$/i.test(f.name)))||(tab==='text'&&(!title||text.length<200))||(['url','feed'].includes(tab)&&!url)||(['file','datasets'].includes(tab)&&!files.length)||(tab==='datasets'&&!preview)} onClick={()=>submit()}>{busy?'Обрабатываем…':tab==='text'?'Сохранить материал':tab==='url'?'Добавить источник':tab==='feed'?'Собрать новости':tab==='datasets'?'Импортировать данные':'Импортировать'}</Button></div></Panel></>}
function RunHistory({uid}:any){const {me}=useApp();const [p,setP]=useState(1);const q=useQuery({queryKey:['history',uid,p],queryFn:()=>api(`/companies/${uid}/runs?page_num=${p}`)});return <><h1>История анализа</h1>{q.isPending?<Loading/>:q.error?<Failure {...q}/>:<><div className="table-scroll" tabIndex={0} role="region" aria-label="История запусков"><table><thead><tr><th>Запуск</th><th>Компания и роль</th><th>Дата</th><th>События</th><th>Статус</th><th>Действия</th></tr></thead><tbody>{q.data.items.map((r:Data)=><tr key={r.id}><td>{r.id.slice(-8)}</td><td>{r.company_id}<br/>{roles[r.role]}</td><td>{date(r.created_at)}</td><td>{r.payload.event_count??'—'}</td><td>{statusLabel[r.status]}</td><td>{r.status.startsWith('completed')&&<Link to={`/companies/${uid}/overview?runId=${r.id}`}>Открыть сводку</Link>}{me.system_role!=='viewer'&&<Link to={'/runs/'+r.id}>Ход анализа</Link>}</td></tr>)}</tbody></table></div><div className="pagination"><Button secondary disabled={p===1} onClick={()=>setP(p-1)}>Назад</Button><span>Страница {p} из {Math.max(1,Math.ceil(q.data.total/20))}</span><Button secondary disabled={p*20>=q.data.total} onClick={()=>setP(p+1)}>Далее</Button></div></>}</>}
function RunTrace(){const {rid}=useParams();const {me}=useApp();const client=useQueryClient();const q=useQuery({queryKey:['trace',rid],queryFn:()=>api('/runs/'+rid),refetchInterval:q=>['queued','running'].includes(q.state.data?.status)?2000:false});if(me.system_role==='viewer')return <Empty title="Нет доступа" text="Ход анализа доступен аналитику"/>;if(q.isPending)return <Loading/>;if(q.error)return <Failure {...q}/>;const r=q.data;return <><h1>Как подготовлен анализ</h1><p className="muted">{r.company_id} · запуск {r.id.slice(-8)}</p><Panel><div className="row between"><h2>{statusLabel[r.status]}</h2>{['queued','running'].includes(r.status)&&<Button secondary onClick={async()=>{await api(`/runs/${rid}/cancel`,{method:'POST'});client.invalidateQueries({queryKey:['trace',rid]})}}>Отменить анализ</Button>}</div><p>{r.mode==='live'?'Анализ новостей':'Учебный анализ'} · {r.payload.steps?.length||0} инструментальных шагов · {r.payload.elapsed_ms??'—'} мс</p><p>Токены: {r.payload.tokens_in} / {r.payload.tokens_out} · Стоимость: {r.payload.cost_rub} ₽</p>{r.payload.error&&<p role="alert">{r.payload.error.message}</p>}</Panel><div className="stack steps">{['План анализа','Профиль компании','Поиск событий','Материалы банка','Ранжирование','Интерпретация','Проверка оснований'].map((name,n)=>{const s=r.payload.steps?.find((s:Data)=>s.number===n+1);return <Panel key={name}><div className="row between"><h2>{n+1}. {name}</h2><span>{s?<Check aria-label="Завершено"/>:'Ожидает'}</span></div>{s&&<><p className="muted">{s.elapsed_ms} мс · {s.tool}</p><details><summary>Результаты и основания</summary><pre>{JSON.stringify(s.result,null,2)}</pre></details></>}</Panel>})}</div></>}
function Comparison(){const {eid}=useParams();const q=useQuery({queryKey:['comparison',eid],queryFn:()=>api(`/events/${eid}/comparison`),refetchInterval:q=>q.state.data?.items.some((v:Data)=>!v.insight)?2000:false});if(q.isPending)return <Loading/>;if(q.error)return <Failure {...q}/>;return <><h1>Одно событие — разное влияние</h1><Panel><Tag>{q.data.event.is_synthetic?'Учебное событие':'Внешний источник'}</Tag><h2>{q.data.event.title}</h2><p>{q.data.event.fact}</p></Panel><div className="comparison-grid">{q.data.items.map((v:Data)=><ComparisonCard key={v.company.id} {...v}/>)}</div></>}
function ComparisonCard({company:c,insight:i}:any){const run=useRun(c.id);return <Panel><h2>{c.id}</h2><p className="muted">{c.industry}</p>{i?<><Tag>{i.is_synthetic?'Учебное событие':'Внешний источник'}</Tag><p>Релевантность: {i.relevance.score}/100</p>{i.relevance.score<50&&<Tag>Требует уточнения</Tag>}<h3>Связь с компанией</h3><p>{i.company_links[0].text}</p><h3>Возможный риск</h3><p>{i.hypotheses.find((h:Data)=>h.kind==='risk')?.text||'Недостаточно оснований для выделения рисков'}</p><h3>Возможность</h3><p>{i.hypotheses.find((h:Data)=>h.kind==='opportunity')?.text||'Недостаточно оснований для выделения возможностей'}</p><h3>Что уточнить</h3><p>{i.actions[0]?.text}</p><Link className="btn secondary" to={`/companies/${c.id}/insights/${i.id}`}>Подробнее</Link></>:<><p>Для этой компании анализ ещё не выполнен</p><Button disabled={run.busy} onClick={run.start}>Проанализировать</Button><Progress run={run}/></>}</Panel>}
function InfluenceMap({uid}:any){const {me}=useApp();const [sp,setSp]=useSearchParams();const [textView,setTextView]=useState(()=>window.innerWidth<768);const [zoom,setZoom]=useState(1);const [pan,setPan]=useState({x:0,y:0});const viewRef=useRef<HTMLDivElement>(null);const [fit,setFit]=useState(1);const drag=useRef<{x:number,y:number,px:number,py:number}|null>(null);const q=useQuery({queryKey:['graph',uid,me.preferences.role],queryFn:()=>api(`/companies/${uid}/graph?role=${me.preferences.role}`)});const [selected,setSelected]=useState('');useEffect(()=>{if(!viewRef.current)return;const update=()=>setFit(Math.min(1,(viewRef.current?.clientWidth||976)/976));update();const obs=new ResizeObserver(update);obs.observe(viewRef.current);return()=>obs.disconnect()},[textView,q.data]);if(q.isPending)return <Loading/>;if(q.error)return <Failure {...q}/>;const g=q.data;const eventNodes=g.nodes.filter((n:Data)=>n.type==='event');const chosen=g.nodes.find((n:Data)=>n.id===(sp.get('eventId')||selected))||eventNodes[0];const coords:Record<string,number[]>={[uid]:[390,220],countries:[720,140],financing:[150,340],industry:[650,340]};eventNodes.forEach((n:Data,k:number)=>coords[n.id]=[[120,75],[570,60],[40,215]][k%3]);const select=(n:Data)=>{setSelected(n.id);if(n.type==='event'){const p=new URLSearchParams(sp);p.set('eventId',n.id);setSp(p)}};return <><div className="page-head"><div><h1>Карта влияния</h1><p className="brief-meta">{uid} · Возможные связи, требующие проверки</p></div><Link className="btn dark-secondary" to={`/companies/${uid}/overview`}>Обзор</Link></div><div className="map-grid"><Panel className="graph-panel"><div className="map-toolbar"><Button secondary onClick={()=>setTextView(!textView)}>{textView?'Открыть карту':'Показать списком'}</Button><div className="actions"><button className="icon-btn" aria-label="Уменьшить масштаб" onClick={()=>setZoom(Math.max(.6,zoom-.2))}>−</button><span>{Math.round(zoom*100)}%</span><button className="icon-btn" aria-label="Увеличить масштаб" onClick={()=>setZoom(Math.min(1.6,zoom+.2))}>+</button><button className="text-btn" onClick={()=>{setZoom(1);setPan({x:0,y:0})}}>По размеру</button></div></div>{!eventNodes.length?<Empty title="Недостаточно данных для карты" text="Запустите анализ в сводке"><Link to={`/companies/${uid}/overview`}>К сводке</Link></Empty>:textView?<div className="graph-list">{g.nodes.map((n:Data)=><button key={n.id} className={chosen?.id===n.id?'selected':''} onClick={()=>select(n)}><strong>{n.label}</strong><span>{n.detail}</span></button>)}<h3>Связи</h3>{g.edges.map((e:Data,n:number)=><p key={n}>{g.nodes.find((v:Data)=>v.id===e.from)?.label} → {g.nodes.find((v:Data)=>v.id===e.to)?.label}: {e.label}</p>)}</div>:<div ref={viewRef} className="graph-viewport" onPointerDown={e=>{if((e.target as HTMLElement).closest?.('button'))return;drag.current={x:e.clientX,y:e.clientY,px:pan.x,py:pan.y};e.currentTarget.setPointerCapture(e.pointerId)}} onPointerMove={e=>{if(drag.current)setPan({x:drag.current.px+e.clientX-drag.current.x,y:drag.current.py+e.clientY-drag.current.y})}} onPointerUp={()=>{drag.current=null}}><div className="graph-canvas" style={{transform:`translate(${pan.x}px,${pan.y}px) scale(${zoom*fit})`}}><svg viewBox="0 0 976 500" className="graph-lines" aria-hidden="true"><defs><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#286bff"/></marker></defs>{g.edges.map((e:Data,n:number)=>{const a=coords[e.from],b=coords[e.to];return <line key={n} x1={a[0]+80} y1={a[1]+35} x2={b[0]+80} y2={b[1]+35} stroke={e.from===chosen?.id?'#EF3124':e.type==='context'?'#929AA9':'#286BFF'} strokeWidth={e.from===chosen?.id?3:2} strokeDasharray={e.type==='context'?'6 6':undefined} markerEnd={e.type==='potential_influence'?'url(#arrow)':undefined}/>})}</svg>{g.nodes.map((n:Data)=><button key={n.id} className={`graph-node ${n.type} ${chosen?.id===n.id?'selected':''}`} style={{left:coords[n.id][0],top:coords[n.id][1]}} onClick={()=>select(n)}>{n.label}</button>)}</div></div>}<p className="muted">Стрелка — возможное влияние. Пунктир — признак профиля. Связь не доказывает причинность.</p></Panel><Panel className="inspector"><Tag>Требует внимания</Tag><h2>{chosen?.label||'Выберите событие'}</h2><p>{chosen?.detail}</p><h3>Аналитика банка</h3><p>{bankEmpty}</p><p className="warning-tile">Не хватает данных о товарах, маршрутах и условиях договоров.</p>{chosen?.insight_id?<Link className="btn primary" to={`/companies/${uid}/insights/${chosen.insight_id}`}>Разобрать сценарий</Link>:<Link className="btn secondary" to={`/companies/${uid}/profile`}>Профиль компании</Link>}</Panel></div></>}
function SettingsPage(){
 const {me,notify}=useApp();const q=useQuery({queryKey:['settings'],queryFn:()=>api('/settings')});
 const [daily,setDaily]=useState(500);const [cap,setCap]=useState(25);const [mode,setMode]=useState('fixture');const [external,setExternal]=useState(false);
 useEffect(()=>{if(q.data){setDaily(q.data.daily_budget);setCap(q.data.run_budget);setMode(q.data.mode);setExternal(q.data.allow_external_context||false)}},[q.data]);
 if(q.isPending)return <Loading/>;if(q.error)return <Failure {...q}/>;const s=q.data;
 return <><h1>Настройки</h1><div className="stack settings-form"><Panel><h2>Предпочтения</h2><p>Роль: {roles[me.preferences.role]}</p><p>Часовой пояс: Москва (UTC+3)</p><Link to="/select-company">Изменить компанию и роль</Link></Panel>
 <Panel><h2>Режим работы</h2><label><input type="radio" name="mode" checked={mode==='fixture'} onChange={()=>setMode('fixture')}/>Локальные правила · учебные и внешние материалы</label><label><input type="radio" name="mode" checked={mode==='live'} disabled={!s.live.ready} onChange={()=>setMode('live')}/>Свежие внешние источники и разрешённая модель</label><p className="muted">Происхождение каждой публикации и фактический метод интерпретации указаны в разборе. При недоступности бесплатной модели используются локальные правила с явной отметкой.</p></Panel>
 {me.system_role==='admin'&&<Panel><h2>AI и бюджет</h2><p>Ключ API: {s.live.key_set?'настроен на сервере':'не настроен'}</p><p>Провайдер: {s.live.provider==='google'?'Google API':'OpenRouter'} · {s.live.free_only?'Только бесплатный тариф; переход на платные модели запрещён':'Тариф настраивается на сервере'}</p>
 <label>Дневной бюджет, ₽<input type="number" min={1} max={500} value={daily} onChange={e=>setDaily(Number(e.target.value))}/></label><label>Лимит одного запуска, ₽<input type="number" min={1} max={daily} value={cap} onChange={e=>setCap(Number(e.target.value))}/></label><p>Использовано сегодня: {s.budget.charged} ₽ · Зарезервировано: {s.budget.reserved} ₽</p><p className="notice">Сбор и анализ запускаются только по кнопке. Пакет новостей для трёх компаний отправляется одним запросом. Автоматических повторов нет.</p>
 <label><input type="checkbox" checked={external} onChange={e=>setExternal(e.target.checked)}/>Разрешаю передавать выбранному провайдеру LLM обезличенные профили трёх компаний и фрагменты источников для анализа</label><p className="muted">Передаются отрасль, ОКВЭД, признаки кредита и лизинга, страны и цитаты. Выручка, платежи, контрагенты и свободные комментарии профиля не отправляются.</p><div className="actions"><Button onClick={async()=>{try{await api('/settings',{method:'PATCH',body:JSON.stringify({daily_budget:daily,run_budget:cap,mode,auto_refresh:false,allow_external_context:external})});q.refetch();notify('Настройки сохранены')}catch(e:any){notify(e.message)}}}>Сохранить настройки</Button><Button secondary disabled={!s.live.ready} onClick={async()=>{try{await api('/settings/test-connection',{method:'POST'});notify('Подключение проверено')}catch(e:any){notify(e.message)}}}>Проверить подключение</Button></div><p className="muted">Проверка подключения проверяет конфигурацию и ключ без генерации ответа. Анализ новостей выполняется отдельной кнопкой одним пакетным запросом.</p></Panel>}
 <CollectionPanel admin={me.system_role==='admin'} notify={notify} role={me.preferences.role}/></div></>;
}
function About(){return <><h1>О проекте</h1><Panel className="about"><h2>Альфа Контекст</h2><p className="lead">Прототип персонализированной новостной аналитики для крупного бизнеса</p><h3>Как работает</h3><p>Профиль → новости → аналитика банка → проверка → персональная сводка.</p><h3>Первый этап</h3><Tag>По отчёту первого этапа</Tag><dl className="profile-values"><dt>Уникальных компаний</dt><dd>85 514</dd><dt>Выручка свыше 15 млрд ₽</dt><dd>115</dd><dt>Крупных клиентов банка</dt><dd>102</dd><dt>Оптовая торговля</dt><dd>62 из 115</dd><dt>Кредитный признак</dt><dd>49</dd><dt>Признак ФТС</dt><dd>57</dd><dt>Входящие и исходящие связи</dt><dd>105</dd></dl><h3>Учебные сценарии</h3><div className="actions"><Link to="/events/fixture-rate-001/compare">Ставка</Link><Link to="/events/fixture-china-001/compare">Китай</Link><Link to="/events/fixture-copper-001/compare">Медь</Link></div><h3>Ограничения</h3><p>Не является гарантией наступления событий. Используются обезличенные данные. Учебные документы не являются публикациями банка.</p><p>AI-помощник: интерфейсная заглушка, модели не подключены.</p><p className="muted">Версия 1.4 · 26.10.2026 · Неофициальный прототип для хакатона</p><Link className="btn primary" to="/select-company">Выбрать компанию</Link></Panel></>}
createRoot(document.getElementById('root')!).render(<QueryClientProvider client={qc}><BrowserRouter><App/></BrowserRouter></QueryClientProvider>);
